func testDocumentoVendaToManyAddOpDDVAdiantamentoEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a DocumentoVenda
	var b, c, d, e AdiantamentoEntidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, documentoVendaDBTypes, false, strmangle.SetComplement(documentoVendaPrimaryKeyColumns, documentoVendaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AdiantamentoEntidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, adiantamentoEntidadeDBTypes, false, strmangle.SetComplement(adiantamentoEntidadePrimaryKeyColumns, adiantamentoEntidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*AdiantamentoEntidade{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddDDVAdiantamentoEntidades(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.DDVID, first.DDVID) {
			t.Error("foreign key was wrong value", a.DDVID, first.DDVID)
		}
		if !queries.Equal(a.DDVID, second.DDVID) {
			t.Error("foreign key was wrong value", a.DDVID, second.DDVID)
		}

		if first.R.DDV != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.DDV != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.DDVAdiantamentoEntidades[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.DDVAdiantamentoEntidades[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.DDVAdiantamentoEntidades().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

