func testDocumentoVendaToOneSetOpCondicaoPagamentoUsingCodpgt(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a DocumentoVenda
	var b, c CondicaoPagamento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, documentoVendaDBTypes, false, strmangle.SetComplement(documentoVendaPrimaryKeyColumns, documentoVendaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, condicaoPagamentoDBTypes, false, strmangle.SetComplement(condicaoPagamentoPrimaryKeyColumns, condicaoPagamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, condicaoPagamentoDBTypes, false, strmangle.SetComplement(condicaoPagamentoPrimaryKeyColumns, condicaoPagamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*CondicaoPagamento{&b, &c} {
		err = a.SetCodpgt(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Codpgt != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.CodpgtDocumentoVendas[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.CodpgtID != x.CodpgtID {
			t.Error("foreign key was wrong value", a.CodpgtID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.CodpgtID))
		reflect.Indirect(reflect.ValueOf(&a.CodpgtID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.CodpgtID != x.CodpgtID {
			t.Error("foreign key was wrong value", a.CodpgtID, x.CodpgtID)
		}
	}
}
